# - Otherwise read from ./top_module.txt to avoid drift between prep metadata and Tcl
if {[info exists ::env(GENUS_TOP)] && [string trim $::env(GENUS_TOP)] ne ""} {
    set TOP [string trim $::env(GENUS_TOP)]
} else {
    set TOP_FILE [file normalize "./top_module.txt"]
    if {![file exists $TOP_FILE]} {
        puts "ERROR: top_module.txt not found ($TOP_FILE). Set GENUS_TOP to override."
        exit 2
    }
    set fh [open $TOP_FILE r]
    set TOP [string trim [read $fh]]
    close $fh
    if {$TOP eq ""} {
        puts "ERROR: top_module.txt is empty. Set GENUS_TOP to override."
        exit 2
    }
}

